  const remembered=recordOpener?.record===previousRecord&&recordOpener.route===state.route?visibleControl(document.querySelectorAll(recordOpener.selector)[recordOpener.index]):null;
  const opener=remembered||document.querySelector(`.concordance-hit[data-hit-key="${CSS.escape(state.lexHit)}"] .hit-evidence`)||document.querySelector(`#main [data-open-record="${previousRecord}"]`)||document.getElementById('main');
