let debounce;
document.addEventListener('input',event=>{
 if(['corpus-search','kwic-search'].includes(event.target.id)){
  const value=event.target.value;clearTimeout(debounce);debounce=setTimeout(()=>navigate({q:value,page:1,lexPage:1,lexHit:''}),160);
 }
});
document.addEventListener('change',event=>{
 const key=event.target.dataset.state;if(!key)return;
 const value=['min','page'].includes(key)?Number(event.target.value):event.target.value;
 navigate({[key]:key==='phenomenonGroup'&&value==='all'?'':value,...(key==='phenomenonGroup'?{phenomenon:'',issue:'',group:'all'}:key==='phenomenon'?{issue:''}:{}),page:1,lexPage:1,lexHit:''});
});
document.addEventListener('click',event=>{
 const hit=event.target.closest('.concordance-hit');if(hit&&!event.target.closest('button,a,mark')){rememberRecordOpener(hit.querySelector('.hit-evidence'),hit.dataset.hitRecord);navigate({record:hit.dataset.hitRecord,lexHit:hit.dataset.hitKey});return;}
 const e=event.target.closest('button,a,mark,[role="button"][data-action]');if(!e)return;
 if(e.classList.contains('skip-link')){event.preventDefault();document.getElementById('main').focus();return;}
 if(e.dataset.language){navigate({lang:e.dataset.language});return;}
 if(e.dataset.openRecord){rememberRecordOpener(e,e.dataset.openRecord);navigate({record:e.dataset.openRecord,...(e.dataset.hit?{lexHit:e.dataset.hit}:{})});return;}
 if(e.dataset.scroll){document.getElementById(e.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}
 if(e.dataset.lexPage){navigate({lexPage:Number(e.dataset.lexPage)});return;}
 if(e.dataset.page){navigate({page:Number(e.dataset.page)});return;}
 if(e.dataset.sort){navigate({sort:e.dataset.sort,dir:state.sort===e.dataset.sort&&state.dir==='asc'?'desc':'asc',page:1});return;}
 if(e.dataset.remove){const key=e.dataset.remove;navigate({[key]:key==='review'?'all':key==='kwicLang'?'all':'',page:1,lexPage:1,lexHit:''});return;}
 if(e.dataset.term){navigate({route:'explore',q:e.dataset.term,page:1,lexPage:1,lexHit:'',record:''});return;}
 if(e.dataset.phenomenon&&!e.dataset.action){navigate({phenomenon:e.dataset.phenomenon,issue:'',page:1,lexPage:1,lexHit:'',record:''});return;}
 if(e.dataset.issue&&!e.dataset.action){navigate({issue:e.dataset.issue,page:1,lexPage:1,lexHit:'',record:''});return;}
 const action=e.dataset.action;
 if(action==='menu'){const nav=document.getElementById('primary-nav'),open=e.getAttribute('aria-expanded')!=='true';e.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open);return;}
 if(action==='dismiss-missing-record'){navigate({record:''});(document.getElementById('corpus-search')||document.getElementById('main')).focus({preventScroll:true});return;}
 if(action==='close-detail'){navigate({record:''});return;}
 if(action==='clear-search'){navigate({q:'',page:1,lexPage:1,lexHit:''});return;}
 if(action==='reset'){navigate({q:'',category:'',review:'all',origin:'',issue:'',page:1,sort:'id',dir:'asc',record:'',metric:'count',group:'all',min:1,kwicLang:'all',lexSort:'record',lexDir:'asc',lexPage:1,lexHit:'',phenomenon:'',phenomenonGroup:'',heatView:'overview'});return;}
 if(action==='lex-direction'){navigate({lexDir:state.lexDir==='asc'?'desc':'asc',lexPage:1});return;}
 if(action==='direction'){navigate({dir:state.dir==='asc'?'desc':'asc',page:1});return;}
 if(action==='category'){navigate({category:e.dataset.category,page:1,lexPage:1,lexHit:''});return;}
 if(action==='review'){navigate({review:e.dataset.review,page:1,lexPage:1,lexHit:''});return;}
 if(action==='review-flow'){navigate({review:e.dataset.review,category:e.dataset.category,page:1,lexPage:1,lexHit:''});return;}
 if(action==='origin'){navigate({origin:e.dataset.origin,page:1,lexPage:1,lexHit:''});return;}
 if(action==='flow'){navigate({origin:e.dataset.origin,category:e.dataset.category,page:1,lexPage:1,lexHit:''});return;}
 if(action==='group-cell'){navigate({category:e.dataset.category,phenomenonGroup:e.dataset.phenomenonGroup,phenomenon:'',issue:'',page:1,lexPage:1,lexHit:''});return;}
 if(action==='phenomenon-cell'){navigate({category:e.dataset.category,phenomenon:e.dataset.phenomenon,issue:'',page:1,lexPage:1,lexHit:''});return;}
 if(action==='cell'){navigate({category:e.dataset.category,issue:e.dataset.issue,page:1,lexPage:1,lexHit:''});return;}
 if(action==='term'){navigate({route:'explore',q:e.dataset.term||state.q,page:1,record:''});return;}
 if(action==='export'){
  const data=sortRecords(filterRecords(records,state),state.sort,state.dir),blob=new Blob(['\ufeff'+csvForRecords(data)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`trilingual_filtered_${data.length}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('announcement').textContent=t('copied');
 }
});
document.addEventListener('keydown',event=>{
 if((event.key==='Enter'||event.key===' ')&&event.target.matches('[role="button"]:not(button)')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}
 if(event.key==='Escape'){const nav=document.getElementById('primary-nav');if(nav?.classList.contains('is-open')){nav.classList.remove('is-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}}
});
document.getElementById('record-dialog').addEventListener('cancel',event=>{event.preventDefault();navigate({record:''});});
function historyChange(){clearTimeout(debounce);if(lastHash===location.hash)return;lastHash=location.hash;state=parseState(location.hash);render();}
addEventListener('resize',()=>{const region=document.querySelector('.concordance-scroll');if(region)region.scrollLeft=Math.max(0,(region.scrollWidth-region.clientWidth)/2);});
addEventListener('hashchange',historyChange);addEventListener('popstate',historyChange);
try {
 const response=await fetch(new URL('./data/corpus.json',import.meta.url));if(!response.ok)throw new Error(`Corpus HTTP ${response.status}`);
 const data=await response.json();records=data.records;meta=data.meta;byId=new Map(records.map(r=>[r.id,r]));
 if(records.length!==500||records.filter(r=>r.human_checked==='yes').length!==50)throw new Error('Unexpected corpus count');
 lastHash=location.hash;render();
} catch(error){console.error(error);document.getElementById('main').innerHTML=`<div class="page-shell empty-state"><h1>${t('errorTitle')}</h1><p>${t('errorBody')}</p><button class="button primary" onclick="location.reload()">${t('retry')}</button></div>`;}
